param([string]$OutputDirectory='.local/revalidation/M192-first-run',[string]$ScratchPrefix='M192')
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $MyInvocation.MyCommand.Path | Split-Path -Parent
$out=Join-Path $root $OutputDirectory
if((Test-Path -LiteralPath $out)-and @(Get-ChildItem -LiteralPath $out -Force).Count-gt0){throw "Refusing to overwrite nonempty output: $out"}
if(-not(Test-Path -LiteralPath $out)){New-Item -ItemType Directory -Path $out|Out-Null}
function Hash192([string]$p){(Get-FileHash -LiteralPath (Join-Path $root $p) -Algorithm SHA256).Hash.ToLowerInvariant()}
$m186='Tools/search_m186_public_route.ps1';$m188='Tools/search_m188_dining_set_placement.ps1';$m191='Tools/search_m191_dining_placement_with_pullouts.ps1';$spec='Architecture/Kitchen_Dining_Porch_Specs.md';$selected='Architecture/Selected_Design_Iteration_2026-10-27/study.json';$bath='Architecture/Direction_D_BathFirst_Adjacency_Study_2026-10-27/study.json'
$hashes=[ordered]@{};foreach($p in @($m186,$m188,$m191,$spec,$selected,$bath)){$hashes[$p]=Hash192 $p}
if($hashes[$selected]-ne'516d6d17e5b6ed6c8ec8cbf7a925cc67c5cc1c0ada194c22ea3fa124e2bb72bb'){throw 'Selected-D source changed; refusing this comparison.'}
$source=[IO.File]::ReadAllText((Join-Path $root $m186));$needle='$obstacles=@($entry,$pantry,$west,$east,$counter,$island,$stools,$halfwall,$wallReturn,$table)+$chairs+$porchWalls'
if(([regex]::Matches($source,[regex]::Escape($needle))).Count-ne1){throw 'M186 obstacle declaration changed; refusing unreviewed generation.'}
# Proposal only: 36 x 60-in table rotated so its 60-in side runs north/south; two chairs on each long side.
$snippet=@'
$table=NewRect186 3.5 16.5 3 5 'rotated-36x60-table'
$chairs=@((NewRect186 1.8333333333 17 1.6666666667 1.5 'west-chair-1'),(NewRect186 1.8333333333 19.5 1.6666666667 1.5 'west-chair-2'),(NewRect186 6.5 17 1.6666666667 1.5 'east-chair-1'),(NewRect186 6.5 19.5 1.6666666667 1.5 'east-chair-2'))
$pullouts=@((NewRect186 0.5 17 3 1.5 'west-chair-1-pullout-36in'),(NewRect186 0.5 19.5 3 1.5 'west-chair-2-pullout-36in'),(NewRect186 6.5 17 3 1.5 'east-chair-1-pullout-36in'),(NewRect186 6.5 19.5 3 1.5 'east-chair-2-pullout-36in'))
$obstacles=@($entry,$pantry,$west,$east,$counter,$island,$stools,$halfwall,$wallReturn,$table)+$chairs+$pullouts+$porchWalls
'@
$prefix=$ScratchPrefix+'-'+[guid]::NewGuid().ToString('N');$scratch='.local/revalidation/'+$prefix+'-route';$scratchFull=Join-Path $root $scratch
if((Test-Path -LiteralPath $scratchFull)-and @(Get-ChildItem -LiteralPath $scratchFull -Force).Count-gt0){throw "Refusing to overwrite scratch: $scratchFull"}
$temp=Join-Path (Split-Path (Join-Path $root $m186) -Parent) ('m192-generated-'+[guid]::NewGuid().ToString('N')+'.ps1')
try{[IO.File]::WriteAllText($temp,$source.Replace($needle,$snippet.TrimEnd()),(New-Object Text.UTF8Encoding($false)));& $temp -OutputDirectory $scratch}finally{if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force}}
$result=Get-Content -LiteralPath (Join-Path $scratchFull 'm186-route-search.json') -Raw|ConvertFrom-Json
$bodyRects=@([pscustomobject]@{x=1.8333333333;y=17;w=1.6666666667;d=1.5},[pscustomobject]@{x=1.8333333333;y=19.5;w=1.6666666667;d=1.5},[pscustomobject]@{x=6.5;y=17;w=1.6666666667;d=1.5},[pscustomobject]@{x=6.5;y=19.5;w=1.6666666667;d=1.5})
$pullRects=@([pscustomobject]@{x=.5;y=17;w=3;d=1.5},[pscustomobject]@{x=.5;y=19.5;w=3;d=1.5},[pscustomobject]@{x=6.5;y=17;w=3;d=1.5},[pscustomobject]@{x=6.5;y=19.5;w=3;d=1.5})
$table=[pscustomobject]@{x=3.5;y=16.5;w=3;d=5}
$inside=@(@($table)+$bodyRects+$pullRects|Where-Object{$_.x-lt-1e-8-or$_.y-lt(14-1e-8)-or$_.x+$_.w-gt(11+1e-8)-or$_.y+$_.d-gt(24+1e-8)}).Count-eq0
$bodyDimensionsValid=(@($bodyRects|Where-Object{-not(([Math]::Abs($_.w-1.5)-lt1e-6-and[Math]::Abs($_.d-1.6666666667)-lt1e-6)-or([Math]::Abs($_.w-1.6666666667)-lt1e-6-and[Math]::Abs($_.d-1.5)-lt1e-6))}).Count-eq0)
$bathData=Get-Content -LiteralPath (Join-Path $root $bath) -Raw|ConvertFrom-Json;$b=@($bathData.selection.main_public_bath.search_windows|Where-Object id-eq'east_of_core')[0]
$checks=@([pscustomobject]@{id='rotated_table_uses_documented_36x60_envelope';pass=([Math]::Abs($table.w-3)-lt1e-8-and[Math]::Abs($table.d-5)-lt1e-8);detail='Table plan envelope remains 36 x 60 in, rotated in plan.'},[pscustomobject]@{id='four_chairs_keep_documented_18x20_envelopes';pass=($bodyRects.Count-eq4-and$bodyDimensionsValid);detail='Four chair body proxies remain 18 x 20 in.'},[pscustomobject]@{id='pullout_zones_remain_in_11x10_dining_block';pass=($inside-and$pullRects.Count-eq4);detail='Table, chair bodies and 36-in-from-table-edge use proxies remain within the M-03 test rectangle.'},[pscustomobject]@{id='m186_grid_and_route_width_unchanged';pass=([double]$result.search.grid_step_ft-eq.25-and[double]$result.search.route_width_in-eq36);detail='The established 0.25-ft grid and 36-in swept-route search are unchanged.'},[pscustomobject]@{id='selected_d_preserved';pass=($hashes[$selected]-eq'516d6d17e5b6ed6c8ec8cbf7a925cc67c5cc1c0ada194c22ea3fa124e2bb72bb');detail='Owner-selected-D source fingerprint is unchanged.'},[pscustomobject]@{id='m06_b_stays_unassigned';pass=([string]$b.status-match'Unassigned');detail='The east/pantry-side M-06/B search window remains unassigned.'},[pscustomobject]@{id='route_result_is_bounded_and_serializable';pass=([bool]$result.search.path_found-or([string]$result.status-eq'no_candidate_on_bounded_quarter_foot_grid'));detail='Record either the candidate route or the no-path result from the bounded search.'})
$passed=@($checks|Where-Object pass).Count;$utf8=New-Object Text.UTF8Encoding($false)
$report=[ordered]@{schema='forever-home-m192-rotated-dining-candidate-v1';status=if($passed-eq$checks.Count){'pass'}else{'fail'};design_result=if($result.search.path_found){'candidate_route_found_requires_review'}else{'no_route_found_for_rotated_table_case'};method='One unapproved 90-degree table orientation, two chairs along each long side and four 36-in-from-table-edge use-zone proxies; M186 search constraints, shell, start, porch-door target and route width remain unchanged.';source_fingerprints_sha256=$hashes;selected_d_sha256=$hashes[$selected];dining_block_ft=@(0,14,11,10);table_rect_ft=$table;chair_body_rectangles_ft=$bodyRects;pullout_use_rectangles_ft=$pullRects;route=[ordered]@{found=[bool]$result.search.path_found;length_ft=$result.search.route_length_ft;turns=$result.search.route_turn_count;reachable_nodes=$result.search.centerline_bounds.reached_node_count;nearest_porch_door_manhattan_ft=$result.search.centerline_bounds.nearest_reachable_to_porch_door.distance_manhattan_ft;waypoints_ft=$result.search.compressed_waypoints_ft;minimum_edge_gap_by_obstacle=$result.search.minimum_edge_gap_by_obstacle;unassigned_travel_ft=$result.search.centerline_zone_lengths_ft.unassigned_ft};checks=[ordered]@{status=if($passed-eq$checks.Count){'pass'}else{'fail'};passed=$passed;total=$checks.Count;items=$checks};limitations=@('One proposal orientation only; no alternative offsets or chair locations were searched.','The 36-in pull-out rectangle is a study interpretation, not a selected chair or occupant envelope.','A route is a grid-screen candidate, not a physical opening, door-clear-width, threshold or occupied-use result.','M-03, the kitchen, the 40 x 42-ft test shell and surrounding room blocks are unapproved comparisons.','M-06/B remains unassigned; no Revit/IFC, selected-D, Incoming RFA or remote state is changed.','No code-compliance, accessibility, structural-safety, professional, permit or construction-readiness conclusion is made.')}
[IO.File]::WriteAllText((Join-Path $out 'm192-rotated-dining-candidate.json'),(($report|ConvertTo-Json -Depth 50)+"`n"),$utf8)
[IO.File]::WriteAllText((Join-Path $out 'm192-checks.json'),(($report.checks|ConvertTo-Json -Depth 30)+"`n"),$utf8)
$csv=[pscustomobject]@{case='rotated_long_side_seating';path_found=[bool]$result.search.path_found;route_length_ft=$result.search.route_length_ft;turns=$result.search.route_turn_count;nearest_porch_door_manhattan_ft=$result.search.centerline_bounds.nearest_reachable_to_porch_door.distance_manhattan_ft;reachable_nodes=$result.search.centerline_bounds.reached_node_count;all_bodies_and_pullouts_inside_11x10=$inside;reserved_pullout_obstacle_count=4}
[IO.File]::WriteAllText((Join-Path $out 'm192-options.csv'),((@($csv|ConvertTo-Csv -NoTypeInformation)-join"`n")+"`n"),$utf8)
Copy-Item -LiteralPath (Join-Path $scratchFull 'm186-route-search.svg') -Destination (Join-Path $out 'm192-layout-and-route.svg')
$null=[xml](Get-Content -LiteralPath (Join-Path $out 'm192-layout-and-route.svg') -Raw)
if($passed-ne$checks.Count){throw "M192 checks failed $passed/$($checks.Count); see $out"}
Write-Output "M192 pass $passed/$($checks.Count); rotated side-seating route found=$($result.search.path_found); M-06/B remains unassigned."
